// Round Constants for AES key expansion
const RCON = [
  0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36,
];

import type { AESStep } from '@/lib/types';
export type { AESStep };

/**
 * Convert a string to a 4x4 state matrix (COLUMN-MAJOR ORDER)
 * AES state is filled column by column
 */
export function stringToState(input: string): number[][] {
  const state: number[][] = [[], [], [], []];
  const paddedInput = input.padEnd(16, '\0');

  for (let col = 0; col < 4; col++) {
    for (let row = 0; row < 4; row++) {
      state[row][col] = paddedInput.charCodeAt(col * 4 + row);
    }
  }

  return state;
}

export function stateToString(state: number[][]): string {
  let result = '';
  for (let col = 0; col < 4; col++) {
    for (let row = 0; row < 4; row++) {
      result += String.fromCharCode(state[row][col]);
    }
  }
  return result;
}

export function stateToHex(state: number[][]): string[][] {
  return state.map(row => row.map(byte => byte.toString(16).padStart(2, '0').toUpperCase()));
}

export function subBytes(state: number[][]): number[][] {
  return state.map(row => row.map(byte => S_BOX[byte]));
}

/**
 * ShiftRows transformation
 * Row 0: no shift
 * Row 1: shift left by 1
 * Row 2: shift left by 2
 * Row 3: shift left by 3
 */
export function shiftRows(state: number[][]): number[][] {
  const newState: number[][] = [[], [], [], []];

  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      newState[row][col] = state[row][(col + row) % 4];
    }
  }

  return newState;
}

/**
 * Galois Field (2^8) multiplication
 */
function gmul(a: number, b: number): number {
  let p = 0;
  let hiBitSet;

  for (let i = 0; i < 8; i++) {
    if (b & 1) {
      p ^= a;
    }
    hiBitSet = a & 0x80;
    a <<= 1;
    if (hiBitSet) {
      a ^= 0x1b; // AES irreducible polynomial x^8 + x^4 + x^3 + x + 1
    }
    b >>= 1;
  }

  return p;
}

/**
 * MixColumns transformation
 * Multiplies each column by the fixed MixColumns matrix
 */
export function mixColumns(state: number[][]): number[][] {
  const newState: number[][] = [[], [], [], []];

  for (let col = 0; col < 4; col++) {
    const s0 = state[0][col];
    const s1 = state[1][col];
    const s2 = state[2][col];
    const s3 = state[3][col];

    newState[0][col] = gmul(s0, 2) ^ gmul(s1, 3) ^ s2 ^ s3;
    newState[1][col] = s0 ^ gmul(s1, 2) ^ gmul(s2, 3) ^ s3;
    newState[2][col] = s0 ^ s1 ^ gmul(s2, 2) ^ gmul(s3, 3);
    newState[3][col] = gmul(s0, 3) ^ s1 ^ s2 ^ gmul(s3, 2);
  }

  return newState;
}

export function addRoundKey(state: number[][], roundKey: number[][]): number[][] {
  return state.map((row, i) => row.map((byte, j) => byte ^ roundKey[i][j]));
}

/**
 * AES-128 Key Expansion (Key Schedule)
 * Generates 11 round keys (44 words) from the initial 128-bit key
 */
export function generateRoundKeys(key: string): number[][][] {
  const paddedKey = key.padEnd(16, '\0');

  const w: number[][] = [];

  for (let i = 0; i < 4; i++) {
    w[i] = [
      paddedKey.charCodeAt(4 * i),
      paddedKey.charCodeAt(4 * i + 1),
      paddedKey.charCodeAt(4 * i + 2),
      paddedKey.charCodeAt(4 * i + 3),
    ];
  }

  // Generate remaining 40 words (total 44 words = 11 round keys)
  for (let i = 4; i < 44; i++) {
    let temp = [...w[i - 1]];

    if (i % 4 === 0) {
      // RotWord: Rotate left by 1 byte
      temp = [temp[1], temp[2], temp[3], temp[0]];

      // SubWord: Apply S-box to each byte
      temp = temp.map(byte => S_BOX[byte]);

      // XOR with round constant
      temp[0] ^= RCON[(i / 4) - 1];
    }

    // XOR with word 4 positions back
    w[i] = w[i - 4].map((byte, j) => byte ^ temp[j]);
  }

  const roundKeys: number[][][] = [];
  for (let round = 0; round < 11; round++) {
    const roundKey: number[][] = [[], [], [], []];
    for (let col = 0; col < 4; col++) {
      const word = w[round * 4 + col];
      for (let row = 0; row < 4; row++) {
        roundKey[row][col] = word[row];
      }
    }
    roundKeys.push(roundKey);
  }

  return roundKeys;
}

/**
 * Perform AES-128 encryption and return all steps for visualization
 */
export function encryptAESWithSteps(plaintext: string, key: string): AESStep[] {
  const steps: AESStep[] = [];
  let state = stringToState(plaintext);
  const roundKeys = generateRoundKeys(key);

  let stepNumber = 0;

  // Initial state
  steps.push({
    stepNumber: stepNumber++,
    type: 'initial',
    title: 'Initial Plaintext',
    description: 'The original plaintext converted to a 4×4 state matrix (column-major order). Each column represents 4 bytes of the input.',
    state: state.map(row => [...row]),
    roundNumber: 0,
  });

  // Initial AddRoundKey (Round 0)
  state = addRoundKey(state, roundKeys[0]);
  steps.push({
    stepNumber: stepNumber++,
    type: 'addRoundKey',
    title: 'Initial AddRoundKey (Round 0)',
    description: 'XOR each byte of the state with the corresponding byte of the initial round key. This is the only operation in Round 0.',
    state: state.map(row => [...row]),
    roundKey: roundKeys[0].map(row => [...row]),
    roundNumber: 0,
  });

  // Main rounds (1-9 for AES-128)
  for (let round = 1; round <= 9; round++) {
    // SubBytes
    state = subBytes(state);
    steps.push({
      stepNumber: stepNumber++,
      type: 'subBytes',
      title: `Round ${round}: SubBytes`,
      description: 'Non-linear substitution step. Each byte is replaced with another byte using the Rijndael S-box lookup table.',
      state: state.map(row => [...row]),
      roundNumber: round,
    });

    // ShiftRows
    state = shiftRows(state);
    steps.push({
      stepNumber: stepNumber++,
      type: 'shiftRows',
      title: `Round ${round}: ShiftRows`,
      description: 'Transposition step. Rows are cyclically shifted left: Row 0 by 0, Row 1 by 1, Row 2 by 2, Row 3 by 3 bytes.',
      state: state.map(row => [...row]),
      roundNumber: round,
    });

    // MixColumns
    state = mixColumns(state);
    steps.push({
      stepNumber: stepNumber++,
      type: 'mixColumns',
      title: `Round ${round}: MixColumns`,
      description: 'Mixing operation using Galois Field (GF(2⁸)) multiplication. Each column is multiplied by a fixed matrix.',
      state: state.map(row => [...row]),
      roundNumber: round,
    });

    // AddRoundKey
    state = addRoundKey(state, roundKeys[round]);
    steps.push({
      stepNumber: stepNumber++,
      type: 'addRoundKey',
      title: `Round ${round}: AddRoundKey`,
      description: `XOR the state with round key ${round} derived from the key schedule.`,
      state: state.map(row => [...row]),
      roundKey: roundKeys[round].map(row => [...row]),
      roundNumber: round,
    });
  }

  // Final round (Round 10) - NO MixColumns
  state = subBytes(state);
  steps.push({
    stepNumber: stepNumber++,
    type: 'subBytes',
    title: 'Round 10: SubBytes (Final Round)',
    description: 'Final SubBytes transformation. The last round omits MixColumns.',
    state: state.map(row => [...row]),
    roundNumber: 10,
  });

  state = shiftRows(state);
  steps.push({
    stepNumber: stepNumber++,
    type: 'shiftRows',
    title: 'Round 10: ShiftRows (Final Round)',
    description: 'Final ShiftRows transformation.',
    state: state.map(row => [...row]),
    roundNumber: 10,
  });

  state = addRoundKey(state, roundKeys[10]);
  steps.push({
    stepNumber: stepNumber++,
    type: 'final',
    title: 'Final Ciphertext',
    description: 'XOR with the final round key (Round 10) to produce the encrypted ciphertext. Encryption complete!',
    state: state.map(row => [...row]),
    roundKey: roundKeys[10].map(row => [...row]),
    roundNumber: 10,
  });

  return steps;
}

/**
 * Block Cipher Modes Implementation
 * Educational visualization of ECB, CBC, and GCM modes
 * Uses simplified XOR-based "encryption" for visualization clarity
 */

import type { BlockModeStep } from '@/lib/types';

// Block size in bytes (simulating 128-bit blocks like AES)
const BLOCK_SIZE = 16;

/**
 * Simple XOR-based block encryption for visualization
 * NOT cryptographically secure - for educational purposes only
 */
function simpleBlockEncrypt(block: string, key: string): string {
  const keyBytes = key.padEnd(BLOCK_SIZE, '\0');
  let result = '';
  for (let i = 0; i < block.length; i++) {
    const encrypted = block.charCodeAt(i) ^ keyBytes.charCodeAt(i % keyBytes.length);
    result += encrypted.toString(16).padStart(2, '0');
  }
  return result;
}

/**
 * XOR two hex strings
 */
function xorHexStrings(a: string, b: string): string {
  const aBytes = hexToBytes(a);
  const bBytes = hexToBytes(b);
  let result = '';
  for (let i = 0; i < Math.max(aBytes.length, bBytes.length); i++) {
    const xored = (aBytes[i] || 0) ^ (bBytes[i] || 0);
    result += xored.toString(16).padStart(2, '0');
  }
  return result;
}

/**
 * Convert hex string to byte array
 */
function hexToBytes(hex: string): number[] {
  const bytes: number[] = [];
  for (let i = 0; i < hex.length; i += 2) {
    bytes.push(parseInt(hex.substr(i, 2), 16) || 0);
  }
  return bytes;
}

/**
 * Convert string to hex
 */
function stringToHex(str: string): string {
  let hex = '';
  for (let i = 0; i < str.length; i++) {
    hex += str.charCodeAt(i).toString(16).padStart(2, '0');
  }
  return hex;
}

/**
 * Pad plaintext to block size (PKCS7 padding)
 */
function padToBlockSize(plaintext: string): string {
  const padding = BLOCK_SIZE - (plaintext.length % BLOCK_SIZE);
  return plaintext + String.fromCharCode(padding).repeat(padding);
}

/**
 * Split plaintext into blocks
 */
function splitIntoBlocks(plaintext: string): string[] {
  const padded = padToBlockSize(plaintext);
  const blocks: string[] = [];
  for (let i = 0; i < padded.length; i += BLOCK_SIZE) {
    blocks.push(padded.slice(i, i + BLOCK_SIZE));
  }
  return blocks;
}

/**
 * Generate a random IV (for visualization, uses predictable values)
 */
function generateIV(): string {
  // Use a fixed IV for reproducible visualization
  return 'a1b2c3d4e5f67890a1b2c3d4e5f67890';
}

/**
 * ECB Mode Encryption with Steps
 * Each block encrypted independently (parallel, reveals patterns)
 */
export function encryptECBWithSteps(plaintext: string, key: string): BlockModeStep[] {
  const steps: BlockModeStep[] = [];
  let stepNumber = 0;

  // Input step
  steps.push({
    type: 'input',
    mode: 'ecb',
    stepNumber: stepNumber++,
    title: 'Input Plaintext',
    description: 'The original message to encrypt. ECB mode will encrypt each 16-byte block independently.',
    values: {
      plaintext: plaintext,
      plaintextHex: stringToHex(plaintext),
    },
  });

  // Split into blocks
  const blocks = splitIntoBlocks(plaintext);
  steps.push({
    type: 'split-blocks',
    mode: 'ecb',
    stepNumber: stepNumber++,
    title: 'Split into Blocks',
    description: `Divide plaintext into ${blocks.length} blocks of ${BLOCK_SIZE} bytes each. PKCS7 padding added if needed.`,
    blocks: blocks.map(b => stringToHex(b)),
    values: {
      blockCount: blocks.length,
      blockSize: BLOCK_SIZE,
    },
  });

  // Encrypt each block independently
  const encryptedBlocks: string[] = [];
  for (let i = 0; i < blocks.length; i++) {
    const encrypted = simpleBlockEncrypt(blocks[i], key);
    encryptedBlocks.push(encrypted);

    steps.push({
      type: 'encrypt-block',
      mode: 'ecb',
      stepNumber: stepNumber++,
      title: `Encrypt Block ${i + 1}`,
      description: `Block ${i + 1} is encrypted directly with the key. No dependency on other blocks - can be parallelized.`,
      blocks: [...encryptedBlocks, ...blocks.slice(i + 1).map(b => stringToHex(b))],
      currentBlock: i,
      values: {
        inputBlock: stringToHex(blocks[i]),
        outputBlock: encrypted,
      },
    });
  }

  // Final output
  const ciphertext = encryptedBlocks.join('');
  steps.push({
    type: 'output',
    mode: 'ecb',
    stepNumber: stepNumber++,
    title: 'ECB Ciphertext',
    description: 'Final encrypted output. WARNING: Identical plaintext blocks produce identical ciphertext blocks, revealing patterns!',
    blocks: encryptedBlocks,
    values: {
      ciphertext: ciphertext,
      blockCount: encryptedBlocks.length,
    },
  });

  return steps;
}

/**
 * CBC Mode Encryption with Steps
 * Each block XORed with previous ciphertext before encryption
 */
export function encryptCBCWithSteps(plaintext: string, key: string): BlockModeStep[] {
  const steps: BlockModeStep[] = [];
  let stepNumber = 0;
  const iv = generateIV();

  // Input step
  steps.push({
    type: 'input',
    mode: 'cbc',
    stepNumber: stepNumber++,
    title: 'Input Plaintext',
    description: 'The original message to encrypt. CBC mode chains blocks together using XOR.',
    iv: iv,
    values: {
      plaintext: plaintext,
      plaintextHex: stringToHex(plaintext),
    },
  });

  // Split into blocks
  const blocks = splitIntoBlocks(plaintext);
  steps.push({
    type: 'split-blocks',
    mode: 'cbc',
    stepNumber: stepNumber++,
    title: 'Split into Blocks + IV',
    description: `Divide plaintext into ${blocks.length} blocks. Generate Initialization Vector (IV) for first block XOR.`,
    blocks: blocks.map(b => stringToHex(b)),
    iv: iv,
    values: {
      blockCount: blocks.length,
      iv: iv,
    },
  });

  // Encrypt each block with chaining
  const encryptedBlocks: string[] = [];
  let previousCiphertext = iv;

  for (let i = 0; i < blocks.length; i++) {
    const blockHex = stringToHex(blocks[i]);

    // XOR with previous ciphertext (or IV for first block)
    const xored = xorHexStrings(blockHex, previousCiphertext);
    steps.push({
      type: 'xor-operation',
      mode: 'cbc',
      stepNumber: stepNumber++,
      title: `XOR Block ${i + 1}`,
      description: i === 0
        ? 'XOR first plaintext block with the IV (Initialization Vector).'
        : `XOR plaintext block ${i + 1} with the previous ciphertext block. This creates the "chain".`,
      blocks: encryptedBlocks,
      currentBlock: i,
      iv: iv,
      previousCiphertext: previousCiphertext,
      values: {
        plainBlock: blockHex,
        xorWith: previousCiphertext,
        result: xored,
      },
    });

    // Encrypt the XORed result
    // For CBC visualization, we simulate encrypting the XORed value
    const encrypted = simpleBlockEncrypt(
      String.fromCharCode(...hexToBytes(xored)),
      key
    );
    encryptedBlocks.push(encrypted);
    previousCiphertext = encrypted;

    steps.push({
      type: 'encrypt-block',
      mode: 'cbc',
      stepNumber: stepNumber++,
      title: `Encrypt Block ${i + 1}`,
      description: `Encrypt the XORed result. Output becomes the "previous ciphertext" for the next block.`,
      blocks: [...encryptedBlocks, ...blocks.slice(i + 1).map(b => stringToHex(b))],
      currentBlock: i,
      iv: iv,
      previousCiphertext: encrypted,
      values: {
        inputBlock: xored,
        outputBlock: encrypted,
      },
    });
  }

  // Final output
  const ciphertext = encryptedBlocks.join('');
  steps.push({
    type: 'output',
    mode: 'cbc',
    stepNumber: stepNumber++,
    title: 'CBC Ciphertext',
    description: 'Final encrypted output. IV must be stored/transmitted with ciphertext. Identical plaintext blocks produce DIFFERENT ciphertext!',
    blocks: encryptedBlocks,
    iv: iv,
    values: {
      ciphertext: ciphertext,
      iv: iv,
      blockCount: encryptedBlocks.length,
    },
  });

  return steps;
}

/**
 * GCM Mode Encryption with Steps
 * Counter mode with authentication tag
 */
export function encryptGCMWithSteps(plaintext: string, key: string): BlockModeStep[] {
  const steps: BlockModeStep[] = [];
  let stepNumber = 0;
  const iv = generateIV().slice(0, 24); // GCM typically uses 96-bit (12-byte) IV
  let counter = 1;

  // Input step
  steps.push({
    type: 'input',
    mode: 'gcm',
    stepNumber: stepNumber++,
    title: 'Input Plaintext',
    description: 'GCM (Galois/Counter Mode) provides both encryption AND authentication (integrity check).',
    iv: iv,
    values: {
      plaintext: plaintext,
      plaintextHex: stringToHex(plaintext),
    },
  });

  // Split into blocks
  const blocks = splitIntoBlocks(plaintext);
  steps.push({
    type: 'split-blocks',
    mode: 'gcm',
    stepNumber: stepNumber++,
    title: 'Split + Initialize Counter',
    description: `Divide plaintext into ${blocks.length} blocks. Initialize counter (nonce + counter value) for CTR mode.`,
    blocks: blocks.map(b => stringToHex(b)),
    iv: iv,
    counter: counter,
    values: {
      blockCount: blocks.length,
      iv: iv,
      initialCounter: counter,
    },
  });

  // Encrypt each block with counter mode
  const encryptedBlocks: string[] = [];
  let ghashInput = '';

  for (let i = 0; i < blocks.length; i++) {
    const blockHex = stringToHex(blocks[i]);

    // Generate keystream from counter
    const counterHex = iv + counter.toString(16).padStart(8, '0');
    const keystream = simpleBlockEncrypt(
      String.fromCharCode(...hexToBytes(counterHex.padEnd(32, '0'))),
      key
    );

    steps.push({
      type: 'encrypt-block',
      mode: 'gcm',
      stepNumber: stepNumber++,
      title: `Encrypt Counter ${counter}`,
      description: `Encrypt the counter block (IV + counter ${counter}) to generate keystream.`,
      blocks: encryptedBlocks,
      currentBlock: i,
      iv: iv,
      counter: counter,
      values: {
        counterBlock: counterHex,
        keystream: keystream,
      },
    });

    // XOR plaintext with keystream
    const encrypted = xorHexStrings(blockHex, keystream);
    encryptedBlocks.push(encrypted);
    ghashInput += encrypted;

    steps.push({
      type: 'xor-operation',
      mode: 'gcm',
      stepNumber: stepNumber++,
      title: `XOR Block ${i + 1}`,
      description: 'XOR plaintext block with keystream to produce ciphertext. Counter mode allows parallel encryption!',
      blocks: [...encryptedBlocks, ...blocks.slice(i + 1).map(b => stringToHex(b))],
      currentBlock: i,
      counter: counter,
      values: {
        plainBlock: blockHex,
        keystream: keystream,
        cipherBlock: encrypted,
      },
    });

    counter++;
  }

  // Generate authentication tag (simplified GHASH simulation)
  const authTag = simpleBlockEncrypt(ghashInput.slice(0, BLOCK_SIZE), key).slice(0, 32);

  // Final output with auth tag
  const ciphertext = encryptedBlocks.join('');
  steps.push({
    type: 'output',
    mode: 'gcm',
    stepNumber: stepNumber++,
    title: 'GCM Ciphertext + Auth Tag',
    description: 'Final output includes ciphertext AND authentication tag. Tag verifies integrity - any tampering is detected!',
    blocks: encryptedBlocks,
    iv: iv,
    authTag: authTag,
    values: {
      ciphertext: ciphertext,
      iv: iv,
      authTag: authTag,
      blockCount: encryptedBlocks.length,
    },
  });

  return steps;
}

/**
 * Demonstrate ECB pattern problem (penguin problem)
 * Returns visual data showing how patterns are preserved
 */
export function demonstrateECBPatternProblem(pattern: string, repetitions: number, key: string): {
  plaintext: string;
  ecbCiphertext: string[];
  cbcCiphertext: string[];
  patternVisible: boolean;
} {
  // Create repeated pattern
  const plaintext = pattern.repeat(repetitions);
  const blocks = splitIntoBlocks(plaintext);

  // ECB encryption (patterns preserved)
  const ecbCiphertext = blocks.map(block => simpleBlockEncrypt(block, key));

  // CBC encryption (patterns hidden)
  let previousCiphertext = generateIV();
  const cbcCiphertext = blocks.map(block => {
    const blockHex = stringToHex(block);
    const xored = xorHexStrings(blockHex, previousCiphertext);
    const encrypted = simpleBlockEncrypt(
      String.fromCharCode(...hexToBytes(xored)),
      key
    );
    previousCiphertext = encrypted;
    return encrypted;
  });

  // Check if ECB shows patterns (identical blocks = identical ciphertext)
  const uniqueECB = new Set(ecbCiphertext).size;
  const patternVisible = uniqueECB < ecbCiphertext.length;

  return {
    plaintext,
    ecbCiphertext,
    cbcCiphertext,
    patternVisible,
  };
}

