// ─── Modular arithmetic helpers ────────────────────────────────────────────────

/**
 * Modular arithmetic: always returns a non-negative result
 */
export function mod(a: number, m: number): number {
  return ((a % m) + m) % m;
}

/**
 * Extended Euclidean Algorithm to find modular inverse
 * Returns x such that (a * x) mod m = 1
 */
export function modInverse(a: number, m: number): number {
  a = mod(a, m);
  if (a === 0) throw new Error('No modular inverse exists for 0');

  let [old_r, r] = [m, a];
  let [old_s, s] = [0, 1];

  while (r !== 0) {
    const quotient = Math.floor(old_r / r);
    [old_r, r] = [r, old_r - quotient * r];
    [old_s, s] = [s, old_s - quotient * s];
  }

  if (old_r !== 1) throw new Error(`No modular inverse: gcd(${a}, ${m}) = ${old_r}`);

  return mod(old_s, m);
}

// ─── Point at infinity (identity element) ──────────────────────────────────────

export const POINT_AT_INFINITY: ECCPoint = { x: 0, y: 0, isInfinity: true };

export function isInfinity(point: ECCPoint): boolean {
  return point.isInfinity === true;
}

// ─── Curve validation ──────────────────────────────────────────────────────────

/**
 * Check if a point lies on the curve y² = x³ + ax + b (mod p)
 */
export function isOnCurve(point: ECCPoint, curve: ECCCurve): boolean {
  if (isInfinity(point)) return true;
  const { x, y } = point;
  const { a, b, p } = curve;
  const lhs = mod(y * y, p);
  const rhs = mod(x * x * x + a * x + b, p);
  return lhs === rhs;
}

/**
 * Find all points on the curve (for small primes only)
 */
export function findAllPoints(curve: ECCCurve): ECCPoint[] {
  const points: ECCPoint[] = [];
  const { a, b, p } = curve;

  for (let x = 0; x < p; x++) {
    const rhs = mod(x * x * x + a * x + b, p);
    for (let y = 0; y < p; y++) {
      if (mod(y * y, p) === rhs) {
        points.push({ x, y });
      }
    }
  }

  return points;
}

// ─── Point operations ──────────────────────────────────────────────────────────

/**
 * Add two points on an elliptic curve
 *
 * Rules:
 * 1. P + O = P (identity element)
 * 2. P + (-P) = O (inverse)
 * 3. P + Q uses the secant line slope
 * 4. P + P uses the tangent line slope (point doubling)
 */
export function pointAdd(P: ECCPoint, Q: ECCPoint, curve: ECCCurve): ECCPoint {
  const { a, p } = curve;

  // Rule 1: Identity element
  if (isInfinity(P)) return Q;
  if (isInfinity(Q)) return P;

  // Rule 2: Inverse (P + (-P) = O)
  if (P.x === Q.x && mod(P.y + Q.y, p) === 0) {
    return POINT_AT_INFINITY;
  }

  let slope: number;

  if (P.x === Q.x && P.y === Q.y) {
    // Rule 4: Point doubling - tangent line
    // slope = (3x² + a) / (2y) mod p
    const numerator = mod(3 * P.x * P.x + a, p);
    const denominator = mod(2 * P.y, p);
    slope = mod(numerator * modInverse(denominator, p), p);
  } else {
    // Rule 3: Point addition - secant line
    // slope = (y2 - y1) / (x2 - x1) mod p
    const numerator = mod(Q.y - P.y, p);
    const denominator = mod(Q.x - P.x, p);
    slope = mod(numerator * modInverse(denominator, p), p);
  }

  // x3 = slope² - x1 - x2 mod p
  const x3 = mod(slope * slope - P.x - Q.x, p);
  // y3 = slope(x1 - x3) - y1 mod p
  const y3 = mod(slope * (P.x - x3) - P.y, p);

  return { x: x3, y: y3 };
}

/**
 * Double a point (P + P)
 * This is a convenience wrapper; pointAdd handles this case internally.
 */
export function pointDouble(P: ECCPoint, curve: ECCCurve): ECCPoint {
  return pointAdd(P, P, curve);
}

/**
 * Negate a point: -P = (x, -y mod p)
 */
export function pointNegate(P: ECCPoint, curve: ECCCurve): ECCPoint {
  if (isInfinity(P)) return POINT_AT_INFINITY;
  return { x: P.x, y: mod(-P.y, curve.p) };
}

/**
 * Scalar multiplication using double-and-add algorithm
 * Computes k * P on the curve
 */
export function scalarMultiply(k: number, P: ECCPoint, curve: ECCCurve): ECCPoint {
  if (k === 0 || isInfinity(P)) return POINT_AT_INFINITY;

  if (k < 0) {
    k = -k;
    P = pointNegate(P, curve);
  }

  let result: ECCPoint = POINT_AT_INFINITY;
  let current: ECCPoint = P;

  while (k > 0) {
    if (k & 1) {
      result = pointAdd(result, current, curve);
    }
    current = pointDouble(current, curve);
    k >>= 1;
  }

  return result;
}

/**
 * Scalar multiplication with intermediate steps for visualization
 */
export function scalarMultiplyWithSteps(
  k: number,
  P: ECCPoint,
  curve: ECCCurve
): { result: ECCPoint; intermediatePoints: ECCPoint[] } {
  const intermediatePoints: ECCPoint[] = [];

  if (k === 0 || isInfinity(P)) {
    return { result: POINT_AT_INFINITY, intermediatePoints };
  }

  let result: ECCPoint = POINT_AT_INFINITY;
  let current: ECCPoint = P;
  let remaining = k;

  while (remaining > 0) {
    if (remaining & 1) {
      result = pointAdd(result, current, curve);
      if (!isInfinity(result)) {
        intermediatePoints.push({ ...result });
      }
    }
    current = pointDouble(current, curve);
    remaining >>= 1;
  }

  return { result, intermediatePoints };
}

// ─── Key generation ────────────────────────────────────────────────────────────

/**
 * Generate an ECC key pair
 * Private key: random integer in [1, n-1]
 * Public key: private key * G
 */
export function generateKeyPair(curve: ECCCurve): ECCKeyPair {
  const privateKey = Math.floor(Math.random() * (curve.n - 1)) + 1;
  const publicKey = scalarMultiply(privateKey, curve.G, curve);

  return { privateKey, publicKey, curve };
}

// ─── ECDH Key Exchange ─────────────────────────────────────────────────────────

/**
 * Perform ECDH key exchange between Alice and Bob
 * Alice: private=a, public=aG
 * Bob: private=b, public=bG
 * Shared secret: a(bG) = b(aG) = abG
 */
export function performECDH(curve: ECCCurve): ECDHResult {
  const alice = generateKeyPair(curve);
  const bob = generateKeyPair(curve);

  // Alice computes shared secret using Bob's public key
  const sharedSecret = scalarMultiply(alice.privateKey, bob.publicKey, curve);

  return {
    alicePrivate: alice.privateKey,
    alicePublic: alice.publicKey,
    bobPrivate: bob.privateKey,
    bobPublic: bob.publicKey,
    sharedSecret,
  };
}

// ─── ECDSA Signing and Verification ────────────────────────────────────────────

/**
 * Simple hash function for educational purposes
 * Maps a message (number) to a value in [1, n-1]
 */
export function simpleHash(message: number, n: number): number {
  // A simplistic hash for demonstration; NOT cryptographically secure
  let hash = message;
  hash = ((hash >> 16) ^ hash) * 0x45d9f3b;
  hash = ((hash >> 16) ^ hash) * 0x45d9f3b;
  hash = (hash >> 16) ^ hash;
  return mod(Math.abs(hash), n - 1) + 1;
}

/**
 * ECDSA Sign
 * Returns signature (r, s)
 */
export function ecdsaSign(
  message: number,
  privateKey: number,
  curve: ECCCurve
): ECDSASignature {
  const { n, G } = curve;
  const z = simpleHash(message, n);

  let r = 0;
  let s = 0;

  // Keep trying until we get valid r and s
  while (r === 0 || s === 0) {
    const k = Math.floor(Math.random() * (n - 1)) + 1;
    const kG = scalarMultiply(k, G, curve);

    if (isInfinity(kG)) continue;

    r = mod(kG.x, n);
    if (r === 0) continue;

    const kInv = modInverse(k, n);
    s = mod(kInv * (z + r * privateKey), n);
  }

  return { r, s };
}

/**
 * ECDSA Verify
 * Returns true if signature is valid
 */
export function ecdsaVerify(
  message: number,
  signature: ECDSASignature,
  publicKey: ECCPoint,
  curve: ECCCurve
): boolean {
  const { n, G } = curve;
  const { r, s } = signature;

  // Check ranges
  if (r < 1 || r >= n || s < 1 || s >= n) return false;

  const z = simpleHash(message, n);
  const sInv = modInverse(s, n);

  const u1 = mod(z * sInv, n);
  const u2 = mod(r * sInv, n);

  const point = pointAdd(
    scalarMultiply(u1, G, curve),
    scalarMultiply(u2, publicKey, curve),
    curve
  );

  if (isInfinity(point)) return false;

  return mod(point.x, n) === r;
}

// ─── Visualization step generators ─────────────────────────────────────────────

/**
 * Generate ECC key pair with visualization steps
 */
export function generateECCWithSteps(curveChoice: 'tiny' | 'small' | 'medium' = 'tiny'): {
  keyPair: ECCKeyPair;
  ecdhResult: ECDHResult;
  steps: ECCStep[];
} {
  const curves = { tiny: TINY_CURVE, small: SMALL_CURVE, medium: MEDIUM_CURVE };
  const curve = curves[curveChoice];

  const steps: ECCStep[] = [];
  let stepNumber = 0;

  // Step 1: Curve setup
  steps.push({
    stepNumber: stepNumber++,
    type: 'curve-setup',
    title: 'Define the Elliptic Curve',
    description: `We define the curve y² = x³ + ${curve.a}x + ${curve.b} (mod ${curve.p}). All operations happen in the finite field F_${curve.p}. This equation creates a set of discrete points that form a mathematical group.`,
    values: { a: curve.a, b: curve.b, p: curve.p },
    formula: `y² = x³ + ${curve.a}x + ${curve.b} (mod ${curve.p})`,
    curve,
  });

  // Step 2: Generator point
  steps.push({
    stepNumber: stepNumber++,
    type: 'generator-point',
    title: 'Select Generator Point (G)',
    description: `Choose the generator point G = (${curve.G.x}, ${curve.G.y}) on the curve. This point, when repeatedly added to itself, generates a cyclic subgroup of order n = ${curve.n}. The generator is publicly known.`,
    values: { Gx: curve.G.x, Gy: curve.G.y, n: curve.n },
    formula: `G = (${curve.G.x}, ${curve.G.y}), order n = ${curve.n}`,
    point: curve.G,
    curve,
  });

  // Step 3: Alice's private key
  const alice = generateKeyPair(curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'private-key',
    title: "Alice's Private Key",
    description: `Alice picks a random secret integer d_A = ${alice.privateKey} in the range [1, ${curve.n - 1}]. This number must remain absolutely secret -- it's the trapdoor that makes ECC secure.`,
    values: { dA: alice.privateKey, min: 1, max: curve.n - 1 },
    formula: `d_A = ${alice.privateKey} (random, 1 <= d_A <= ${curve.n - 1})`,
    curve,
  });

  // Step 4: Scalar multiplication to get public key
  const { intermediatePoints } = scalarMultiplyWithSteps(alice.privateKey, curve.G, curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'scalar-multiply',
    title: 'Scalar Multiplication (Double-and-Add)',
    description: `Compute Q_A = d_A * G = ${alice.privateKey} * (${curve.G.x}, ${curve.G.y}) using the double-and-add algorithm. This repeatedly doubles G and adds intermediate results based on the binary representation of d_A. Finding d_A from Q_A is the Elliptic Curve Discrete Logarithm Problem (ECDLP) -- believed to be computationally infeasible for large curves.`,
    values: {
      dA: alice.privateKey,
      Gx: curve.G.x,
      Gy: curve.G.y,
      steps: intermediatePoints.length,
    },
    formula: `Q_A = d_A × G = ${alice.privateKey} × (${curve.G.x}, ${curve.G.y})`,
    calculation: `Double-and-add: ${alice.privateKey} in binary = ${alice.privateKey.toString(2)}`,
    curve,
  });

  // Step 5: Public key result
  steps.push({
    stepNumber: stepNumber++,
    type: 'public-key',
    title: "Alice's Public Key",
    description: `Alice's public key is Q_A = (${alice.publicKey.x}, ${alice.publicKey.y}). She shares this openly. Anyone can verify it lies on the curve: ${alice.publicKey.y}² mod ${curve.p} = (${alice.publicKey.x}³ + ${curve.a}*${alice.publicKey.x} + ${curve.b}) mod ${curve.p}.`,
    values: { QAx: alice.publicKey.x, QAy: alice.publicKey.y },
    formula: `Q_A = (${alice.publicKey.x}, ${alice.publicKey.y})`,
    calculation: `Verify: ${alice.publicKey.y}² mod ${curve.p} = ${mod(alice.publicKey.y * alice.publicKey.y, curve.p)}, ${alice.publicKey.x}³ + ${curve.a}·${alice.publicKey.x} + ${curve.b} mod ${curve.p} = ${mod(alice.publicKey.x * alice.publicKey.x * alice.publicKey.x + curve.a * alice.publicKey.x + curve.b, curve.p)}`,
    point: alice.publicKey,
    curve,
  });

  // Step 6: Bob's keys for ECDH
  const bob = generateKeyPair(curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'shared-secret',
    title: 'ECDH: Bob Generates His Key Pair',
    description: `Bob picks d_B = ${bob.privateKey} and computes Q_B = d_B * G = (${bob.publicKey.x}, ${bob.publicKey.y}). Alice and Bob exchange public keys Q_A and Q_B over an insecure channel.`,
    values: { dB: bob.privateKey, QBx: bob.publicKey.x, QBy: bob.publicKey.y },
    formula: `Q_B = d_B × G = ${bob.privateKey} × (${curve.G.x}, ${curve.G.y})`,
    point: bob.publicKey,
    curve,
  });

  // Step 7: Shared secret computation
  const sharedSecret = scalarMultiply(alice.privateKey, bob.publicKey, curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'shared-secret',
    title: 'ECDH: Compute Shared Secret',
    description: `Alice computes S = d_A * Q_B = ${alice.privateKey} * (${bob.publicKey.x}, ${bob.publicKey.y}) = (${sharedSecret.x}, ${sharedSecret.y}). Bob computes S = d_B * Q_A = ${bob.privateKey} * (${alice.publicKey.x}, ${alice.publicKey.y}) and gets the same point! An eavesdropper who knows Q_A and Q_B cannot compute S without solving the ECDLP.`,
    values: {
      Sx: isInfinity(sharedSecret) ? 'Infinity' : sharedSecret.x,
      Sy: isInfinity(sharedSecret) ? 'Infinity' : sharedSecret.y,
    },
    formula: `S = d_A × Q_B = d_B × Q_A`,
    calculation: `Alice: ${alice.privateKey} × (${bob.publicKey.x}, ${bob.publicKey.y}) = (${isInfinity(sharedSecret) ? 'O' : `${sharedSecret.x}, ${sharedSecret.y}`})`,
    point: isInfinity(sharedSecret) ? undefined : sharedSecret,
    curve,
  });

  // Step 8: ECDSA signing
  const testMessage = 42;
  const signature = ecdsaSign(testMessage, alice.privateKey, curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'signing',
    title: 'ECDSA: Sign a Message',
    description: `Alice signs message m = ${testMessage}. She picks a random k, computes kG, and derives signature (r, s) = (${signature.r}, ${signature.s}). The signature proves Alice authored the message without revealing her private key.`,
    values: { message: testMessage, r: signature.r, s: signature.s },
    formula: 'r = (kG).x mod n, s = k⁻¹(z + r·d_A) mod n',
    calculation: `Sign(${testMessage}) = (r=${signature.r}, s=${signature.s})`,
    curve,
  });

  // Step 9: ECDSA verification
  const isValid = ecdsaVerify(testMessage, signature, alice.publicKey, curve);
  steps.push({
    stepNumber: stepNumber++,
    type: 'verification',
    title: 'ECDSA: Verify Signature',
    description: `Bob verifies the signature using Alice's public key Q_A. He computes u1*G + u2*Q_A and checks if the x-coordinate equals r. Result: ${isValid ? 'VALID -- the signature is authentic!' : 'INVALID -- something went wrong.'}`,
    values: {
      message: testMessage,
      r: signature.r,
      s: signature.s,
      valid: isValid ? 'YES' : 'NO',
    },
    formula: 'u1 = z·s⁻¹ mod n, u2 = r·s⁻¹ mod n, verify (u1·G + u2·Q_A).x = r',
    calculation: `Verify(${testMessage}, (${signature.r}, ${signature.s})) = ${isValid}`,
    curve,
  });

  // Step 10: Complete
  steps.push({
    stepNumber: stepNumber++,
    type: 'complete',
    title: 'ECC Operations Complete!',
    description: `Key pair generated, ECDH shared secret established, and ECDSA signature verified. ECC achieves the same security as RSA with much smaller keys: a 256-bit ECC key provides comparable security to a 3072-bit RSA key.`,
    values: {
      curve: `y² = x³ + ${curve.a}x + ${curve.b} (mod ${curve.p})`,
      privateKey: alice.privateKey,
      publicKeyX: alice.publicKey.x,
      publicKeyY: alice.publicKey.y,
    },
    curve,
  });

  const ecdhResult: ECDHResult = {
    alicePrivate: alice.privateKey,
    alicePublic: alice.publicKey,
    bobPrivate: bob.privateKey,
    bobPublic: bob.publicKey,
    sharedSecret,
  };

  return { keyPair: alice, ecdhResult, steps };
}

/**
 * Simplified Hash Function for Educational Visualization
 *
 * IMPORTANT: This uses FNV-1a (32-bit) for simplicity, NOT SHA-256.
 * Real-world applications should use Web Crypto API's SHA-256.
 * This implementation prioritizes visualization clarity over cryptographic security.
 */

import type { HashStep } from '@/lib/types';
export type { HashStep };

export function simpleHash(input: string): string {
  let hash = 0x811c9dc5; // FNV offset basis

  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash *= 0x01000193; // FNV prime
    hash = hash >>> 0; // Convert to 32-bit unsigned
  }

  return hash.toString(16).padStart(8, '0');
}

export function stringToBinary(str: string): string {
  return Array.from(str)
    .map(char => char.charCodeAt(0).toString(2).padStart(8, '0'))
    .join(' ');
}

export function demonstrateAvalancheEffect(input: string): Array<{
  input: string;
  hash: string;
  bitsChanged: number;
}> {
  const results = [];
  const originalHash = simpleHash(input);

  results.push({
    input: input,
    hash: originalHash,
    bitsChanged: 0,
  });

  const variations = [
    input + ' ', // Add space
    input.slice(0, -1), // Remove last character
    input.charAt(0).toUpperCase() + input.slice(1), // Capitalize first
    input.toLowerCase(), // All lowercase
    input.toUpperCase(), // All uppercase
  ];

  variations.forEach(variant => {
    if (variant !== input) {
      const variantHash = simpleHash(variant);
      const bitsChanged = countBitDifference(originalHash, variantHash);
      results.push({
        input: variant,
        hash: variantHash,
        bitsChanged,
      });
    }
  });

  return results;
}

function countBitDifference(hash1: string, hash2: string): number {
  let count = 0;
  const maxLength = Math.max(hash1.length, hash2.length);

  for (let i = 0; i < maxLength; i++) {
    const byte1 = parseInt(hash1[i] || '0', 16);
    const byte2 = parseInt(hash2[i] || '0', 16);
    const xor = byte1 ^ byte2;

    // Count set bits in XOR result
    let bits = xor;
    while (bits) {
      count += bits & 1;
      bits >>= 1;
    }
  }

  return count;
}

export function hashWithSteps(input: string): HashStep[] {
  const steps: HashStep[] = [];
  let stepNumber = 0;

  steps.push({
    stepNumber: stepNumber++,
    type: 'input',
    title: 'Input Message',
    description: `Original input: "${input}". This is the message we want to hash.`,
    data: {
      input,
    },
  });

  const binary = stringToBinary(input.slice(0, 16)); // Limit for display
  steps.push({
    stepNumber: stepNumber++,
    type: 'preprocessing',
    title: 'Convert to Binary',
    description: 'The message is converted to binary (8 bits per character) for processing.',
    data: {
      input,
      binary,
    },
  });

  steps.push({
    stepNumber: stepNumber++,
    type: 'initialization',
    title: 'Initialize Hash Value',
    description: 'Start with an initial hash value (based on FNV-1a algorithm for this demo).',
    data: {
      input,
      hash: '811c9dc5',
    },
  });

  const chunks = input.match(/.{1,4}/g) || [input];
  steps.push({
    stepNumber: stepNumber++,
    type: 'compression',
    title: 'Process Message',
    description: 'The message is processed in chunks, mixing bits through XOR and multiplication operations.',
    data: {
      input,
      chunks,
    },
  });

  const finalHash = simpleHash(input);
  steps.push({
    stepNumber: stepNumber++,
    type: 'output',
    title: 'Final Hash Output',
    description: `The final 32-bit hash (8 hexadecimal characters): ${finalHash}. Note: This is a simplified FNV-1a hash for educational purposes. Production systems use SHA-256 (256-bit) or similar.`,
    data: {
      input,
      hash: finalHash,
    },
  });

  return steps;
}

export function compareHashes(input1: string, input2: string): {
  input1: string;
  hash1: string;
  input2: string;
  hash2: string;
  similarity: number;
  bitsChanged: number;
} {
  const hash1 = simpleHash(input1);
  const hash2 = simpleHash(input2);
  const bitsChanged = countBitDifference(hash1, hash2);
  const totalBits = hash1.length * 4; // 4 bits per hex character
  const similarity = Math.round((1 - bitsChanged / totalBits) * 100);

  return {
    input1,
    hash1,
    input2,
    hash2,
    similarity,
    bitsChanged,
  };
}

/**
 * HMAC (Hash-based Message Authentication Code) Implementation
 * Educational visualization of HMAC construction
 *
 * IMPORTANT: Uses simplified FNV-1a hash for visualization clarity.
 * Real-world HMAC uses SHA-256 or similar via Web Crypto API.
 *
 * HMAC(key, message) = Hash((key XOR opad) || Hash((key XOR ipad) || message))
 * ipad = 0x36 repeated, opad = 0x5c repeated
 */

import { simpleHash } from './hash';
import type { HMACStep } from '@/lib/types/hmac';

export type { HMACStep };

const BLOCK_SIZE = 16; // Simplified block size for visualization

/**
 * Pad or truncate key to block size
 */
function normalizeKey(key: string): string {
  if (key.length > BLOCK_SIZE) {
    // If key is longer than block size, hash it first
    return simpleHash(key).padEnd(BLOCK_SIZE, '\0');
  }
  return key.padEnd(BLOCK_SIZE, '\0');
}

/**
 * XOR a string with a repeated byte value
 */
function xorWithByte(str: string, byte: number): string {
  return Array.from(str)
    .map((ch) => String.fromCharCode(ch.charCodeAt(0) ^ byte))
    .join('');
}

/**
 * Convert string to hex representation
 */
function stringToHex(str: string): string {
  return Array.from(str)
    .map((ch) => ch.charCodeAt(0).toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Compute HMAC using the simplified hash function
 */
export function hmac(key: string, message: string): string {
  const normalizedKey = normalizeKey(key);
  const innerKey = xorWithByte(normalizedKey, 0x36); // key XOR ipad
  const outerKey = xorWithByte(normalizedKey, 0x5c); // key XOR opad

  const innerHash = simpleHash(innerKey + message);
  const finalHash = simpleHash(outerKey + innerHash);

  return finalHash;
}

/**
 * Demonstrate why Hash(key || message) is NOT secure (length extension vulnerability)
 */
export function demonstrateLengthExtension(key: string, message: string): {
  naiveHash: string;
  hmacHash: string;
  extendedMessage: string;
  extendedNaiveHash: string;
  extendedHmacHash: string;
  naiveCollides: boolean;
} {
  const naiveHash = simpleHash(key + message);
  const hmacHash = hmac(key, message);

  // Simulate length extension: attacker appends data without knowing key
  const extendedMessage = message + '&admin=true';
  const extendedNaiveHash = simpleHash(key + extendedMessage);
  const extendedHmacHash = hmac(key, extendedMessage);

  return {
    naiveHash,
    hmacHash,
    extendedMessage,
    extendedNaiveHash,
    extendedHmacHash,
    // In a real length extension attack, the attacker can forge the naive hash
    // without knowing the key. This simplified demo shows the concept.
    naiveCollides: false,
  };
}

/**
 * Verify an HMAC value
 */
export function verifyHmac(key: string, message: string, expectedHmac: string): boolean {
  const computed = hmac(key, message);
  return computed === expectedHmac;
}

/**
 * Compute HMAC with detailed steps for visualization
 */
export function hmacWithSteps(key: string, message: string): HMACStep[] {
  const steps: HMACStep[] = [];
  let stepNumber = 0;

  // Step 1: Input
  steps.push({
    stepNumber: stepNumber++,
    type: 'input',
    title: 'HMAC Inputs',
    description: `HMAC takes two inputs: a secret key and a message. The key authenticates the sender, while the message is the data to protect.`,
    values: {
      key,
      message,
      keyLength: `${key.length} bytes`,
      messageLength: `${message.length} bytes`,
    },
  });

  // Step 2: Key padding
  const normalizedKey = normalizeKey(key);
  const keyWasTruncated = key.length > BLOCK_SIZE;
  steps.push({
    stepNumber: stepNumber++,
    type: 'key-padding',
    title: 'Normalize Key',
    description: keyWasTruncated
      ? `Key is longer than block size (${BLOCK_SIZE} bytes), so it is hashed first, then padded with zeros to fill the block.`
      : `Key is padded with zeros to match the block size of ${BLOCK_SIZE} bytes.`,
    values: {
      originalKey: key,
      originalKeyHex: stringToHex(key),
      normalizedKeyHex: stringToHex(normalizedKey),
      blockSize: `${BLOCK_SIZE} bytes`,
      action: keyWasTruncated ? 'Hashed then padded' : 'Zero-padded',
    },
  });

  // Step 3: Inner key (key XOR ipad)
  const innerKey = xorWithByte(normalizedKey, 0x36);
  steps.push({
    stepNumber: stepNumber++,
    type: 'inner-hash',
    title: 'Create Inner Key (Key XOR ipad)',
    description: 'XOR the padded key with ipad (0x36 repeated). The ipad value 0x36 was chosen to create maximum bit diffusion.',
    values: {
      normalizedKeyHex: stringToHex(normalizedKey),
      ipad: '0x36 (repeated)',
      innerKeyHex: stringToHex(innerKey),
    },
  });

  // Step 4: Inner hash
  const innerInput = innerKey + message;
  const innerHash = simpleHash(innerInput);
  steps.push({
    stepNumber: stepNumber++,
    type: 'inner-hash',
    title: 'Compute Inner Hash',
    description: 'Hash the concatenation of the inner key and the message. This is the first pass of the two-pass HMAC construction.',
    values: {
      operation: 'Hash(innerKey || message)',
      innerKeyHex: stringToHex(innerKey).slice(0, 32) + '...',
      message,
      innerHash,
    },
  });

  // Step 5: Outer key (key XOR opad)
  const outerKey = xorWithByte(normalizedKey, 0x5c);
  steps.push({
    stepNumber: stepNumber++,
    type: 'outer-hash',
    title: 'Create Outer Key (Key XOR opad)',
    description: 'XOR the padded key with opad (0x5c repeated). Using different padding constants for inner and outer passes prevents related-key attacks.',
    values: {
      normalizedKeyHex: stringToHex(normalizedKey),
      opad: '0x5c (repeated)',
      outerKeyHex: stringToHex(outerKey),
    },
  });

  // Step 6: Outer hash (final HMAC)
  const finalHash = simpleHash(outerKey + innerHash);
  steps.push({
    stepNumber: stepNumber++,
    type: 'outer-hash',
    title: 'Compute Outer Hash (Final HMAC)',
    description: 'Hash the concatenation of the outer key and the inner hash. This second pass completes the HMAC and provides protection against length extension attacks.',
    values: {
      operation: 'Hash(outerKey || innerHash)',
      outerKeyHex: stringToHex(outerKey).slice(0, 32) + '...',
      innerHash,
      finalHmac: finalHash,
    },
  });

  // Step 7: Output
  steps.push({
    stepNumber: stepNumber++,
    type: 'output',
    title: 'HMAC Output',
    description: `The final HMAC value: ${finalHash}. This tag can be sent alongside the message. The recipient, who also knows the secret key, can recompute the HMAC and verify it matches.`,
    values: {
      hmac: finalHash,
      formula: 'HMAC(K, m) = H((K XOR opad) || H((K XOR ipad) || m))',
      key,
      message,
    },
  });

  // Step 8: Verification demo
  const isValid = verifyHmac(key, message, finalHash);
  steps.push({
    stepNumber: stepNumber++,
    type: 'verify',
    title: 'Verification',
    description: 'The recipient recomputes the HMAC with the shared secret key and compares it to the received tag. If they match, the message is authentic and unmodified.',
    values: {
      receivedHmac: finalHash,
      computedHmac: finalHash,
      match: isValid ? 'YES - Message is authentic' : 'NO - Message was tampered with',
    },
  });

  return steps;
}

/**
 * Padding Schemes Implementation
 * Educational visualization of PKCS#7, Zero Padding, and ANSI X.923
 *
 * Padding ensures plaintext is a multiple of the block size,
 * which is required for block cipher modes like ECB and CBC.
 */

import type { PaddingScheme, PaddingStep } from '@/lib/types/padding';

export type { PaddingScheme, PaddingStep };

/**
 * Convert string to byte array
 */
function stringToBytes(str: string): number[] {
  return Array.from(str).map((ch) => ch.charCodeAt(0));
}

/**
 * Convert byte array to hex string
 */
function bytesToHex(bytes: number[]): string {
  return bytes.map((b) => b.toString(16).padStart(2, '0')).join(' ');
}

/**
 * Convert byte array to displayable string (showing control chars as dots)
 */
function bytesToDisplay(bytes: number[]): string {
  return bytes.map((b) => (b >= 32 && b <= 126 ? String.fromCharCode(b) : '.')).join('');
}

/**
 * Apply PKCS#7 padding
 * Each padding byte equals the number of padding bytes added
 * e.g., if 3 bytes of padding needed: [03, 03, 03]
 * If input is already block-aligned, add a full block of padding
 */
export function pkcs7Pad(data: number[], blockSize: number): number[] {
  const paddingNeeded = blockSize - (data.length % blockSize);
  const padding = new Array(paddingNeeded).fill(paddingNeeded);
  return [...data, ...padding];
}

/**
 * Remove PKCS#7 padding
 */
export function pkcs7Unpad(data: number[]): number[] {
  if (data.length === 0) return data;
  const lastByte = data[data.length - 1];
  if (lastByte < 1 || lastByte > data.length) {
    throw new Error('Invalid PKCS#7 padding');
  }
  // Verify all padding bytes are correct
  for (let i = data.length - lastByte; i < data.length; i++) {
    if (data[i] !== lastByte) {
      throw new Error('Invalid PKCS#7 padding');
    }
  }
  return data.slice(0, data.length - lastByte);
}

/**
 * Apply zero padding
 * Fill remaining bytes with 0x00
 * Note: ambiguous if original data ends with zeros
 */
export function zeroPad(data: number[], blockSize: number): number[] {
  const paddingNeeded = blockSize - (data.length % blockSize);
  if (paddingNeeded === blockSize && data.length > 0) return [...data];
  const padding = new Array(paddingNeeded === blockSize ? blockSize : paddingNeeded).fill(0);
  return [...data, ...padding];
}

/**
 * Remove zero padding (removes trailing zeros)
 */
export function zeroUnpad(data: number[]): number[] {
  let end = data.length;
  while (end > 0 && data[end - 1] === 0) {
    end--;
  }
  return data.slice(0, end);
}

/**
 * Apply ANSI X.923 padding
 * All padding bytes are 0x00 except the last, which is the count of padding bytes
 * e.g., if 3 bytes needed: [00, 00, 03]
 */
export function ansiX923Pad(data: number[], blockSize: number): number[] {
  const paddingNeeded = blockSize - (data.length % blockSize);
  const padding = new Array(paddingNeeded).fill(0);
  padding[padding.length - 1] = paddingNeeded;
  return [...data, ...padding];
}

/**
 * Remove ANSI X.923 padding
 */
export function ansiX923Unpad(data: number[]): number[] {
  if (data.length === 0) return data;
  const lastByte = data[data.length - 1];
  if (lastByte < 1 || lastByte > data.length) {
    throw new Error('Invalid ANSI X.923 padding');
  }
  return data.slice(0, data.length - lastByte);
}

/**
 * Apply padding with a given scheme
 */
export function pad(data: number[], blockSize: number, scheme: PaddingScheme): number[] {
  switch (scheme) {
    case 'pkcs7':
      return pkcs7Pad(data, blockSize);
    case 'zero':
      return zeroPad(data, blockSize);
    case 'ansi-x923':
      return ansiX923Pad(data, blockSize);
  }
}

/**
 * Remove padding with a given scheme
 */
export function unpad(data: number[], scheme: PaddingScheme): number[] {
  switch (scheme) {
    case 'pkcs7':
      return pkcs7Unpad(data);
    case 'zero':
      return zeroUnpad(data);
    case 'ansi-x923':
      return ansiX923Unpad(data);
  }
}

/**
 * Split byte array into blocks for display
 */
function splitIntoBlocks(data: number[], blockSize: number): number[][] {
  const blocks: number[][] = [];
  for (let i = 0; i < data.length; i += blockSize) {
    blocks.push(data.slice(i, i + blockSize));
  }
  return blocks;
}

/**
 * Get human-readable scheme name
 */
function schemeName(scheme: PaddingScheme): string {
  switch (scheme) {
    case 'pkcs7':
      return 'PKCS#7';
    case 'zero':
      return 'Zero Padding';
    case 'ansi-x923':
      return 'ANSI X.923';
  }
}

/**
 * Pad with detailed steps for visualization
 */
export function padWithSteps(
  input: string,
  blockSize: number,
  scheme: PaddingScheme
): PaddingStep[] {
  const steps: PaddingStep[] = [];
  let stepNumber = 0;
  const inputBytes = stringToBytes(input);

  // Step 1: Input
  steps.push({
    stepNumber: stepNumber++,
    type: 'input',
    title: 'Input Data',
    description: `The plaintext "${input}" needs to be padded so its length is a multiple of the block size before encryption.`,
    scheme,
    values: {
      plaintext: input,
      plaintextHex: bytesToHex(inputBytes),
      length: inputBytes.length,
      blockSize,
      scheme: schemeName(scheme),
    },
  });

  // Step 2: Measure
  const remainder = inputBytes.length % blockSize;
  const paddingNeeded =
    remainder === 0 && scheme === 'pkcs7'
      ? blockSize
      : remainder === 0 && inputBytes.length > 0
        ? 0
        : blockSize - remainder;

  steps.push({
    stepNumber: stepNumber++,
    type: 'measure',
    title: 'Measure Block Alignment',
    description:
      remainder === 0 && scheme !== 'pkcs7' && inputBytes.length > 0
        ? `Input is already aligned to the ${blockSize}-byte block size. ${scheme === 'zero' ? 'Zero padding adds nothing.' : 'ANSI X.923 adds a full block.'}`
        : `Input is ${inputBytes.length} bytes. With a ${blockSize}-byte block size, ${paddingNeeded} bytes of padding are needed.`,
    scheme,
    values: {
      inputLength: inputBytes.length,
      blockSize,
      remainder,
      paddingNeeded: paddingNeeded === 0 ? blockSize : paddingNeeded,
    },
  });

  // Step 3: Calculate padding bytes
  const actualPaddingNeeded = paddingNeeded === 0 ? blockSize : paddingNeeded;
  let paddingBytes: number[];

  switch (scheme) {
    case 'pkcs7':
      paddingBytes = new Array(actualPaddingNeeded).fill(actualPaddingNeeded);
      steps.push({
        stepNumber: stepNumber++,
        type: 'calculate-padding',
        title: 'Calculate PKCS#7 Padding',
        description: `Each padding byte is set to the number of padding bytes added (${actualPaddingNeeded}). This makes unpadding unambiguous -- the last byte always tells you how many to remove.`,
        scheme,
        values: {
          paddingValue: actualPaddingNeeded,
          paddingHex: bytesToHex(paddingBytes),
          rule: `All bytes = 0x${actualPaddingNeeded.toString(16).padStart(2, '0')}`,
        },
        paddingBytes,
      });
      break;

    case 'zero':
      paddingBytes = new Array(actualPaddingNeeded).fill(0);
      steps.push({
        stepNumber: stepNumber++,
        type: 'calculate-padding',
        title: 'Calculate Zero Padding',
        description: `Fill remaining bytes with 0x00. Warning: this scheme is ambiguous if the original data ends with zero bytes.`,
        scheme,
        values: {
          paddingHex: bytesToHex(paddingBytes),
          rule: 'All bytes = 0x00',
          warning: 'Cannot distinguish data zeros from padding zeros',
        },
        paddingBytes,
      });
      break;

    case 'ansi-x923': {
      paddingBytes = new Array(actualPaddingNeeded).fill(0);
      paddingBytes[paddingBytes.length - 1] = actualPaddingNeeded;
      steps.push({
        stepNumber: stepNumber++,
        type: 'calculate-padding',
        title: 'Calculate ANSI X.923 Padding',
        description: `All padding bytes are 0x00 except the last byte, which stores the padding count (${actualPaddingNeeded}). This is unambiguous like PKCS#7 but uses zeros for intermediate bytes.`,
        scheme,
        values: {
          paddingHex: bytesToHex(paddingBytes),
          lastByte: actualPaddingNeeded,
          rule: 'Zeros + count byte at end',
        },
        paddingBytes,
      });
      break;
    }
  }

  // Step 4: Apply padding
  const padded = pad(inputBytes, blockSize, scheme);
  steps.push({
    stepNumber: stepNumber++,
    type: 'apply-padding',
    title: 'Apply Padding',
    description: `Append the ${schemeName(scheme)} padding bytes to the original data. The result is now ${padded.length} bytes, a multiple of the ${blockSize}-byte block size.`,
    scheme,
    values: {
      originalHex: bytesToHex(inputBytes),
      paddedHex: bytesToHex(padded),
      paddedDisplay: bytesToDisplay(padded),
      totalLength: padded.length,
    },
    paddingBytes: paddingBytes!,
  });

  // Step 5: Show blocks
  const blocks = splitIntoBlocks(padded, blockSize);
  steps.push({
    stepNumber: stepNumber++,
    type: 'show-blocks',
    title: 'Block View',
    description: `The padded data splits evenly into ${blocks.length} block(s) of ${blockSize} bytes each. Each block can now be processed by a block cipher independently.`,
    scheme,
    values: {
      blockCount: blocks.length,
      blockSize,
    },
    blocks: blocks.map((b) => bytesToHex(b)),
    paddingBytes: paddingBytes!,
  });

  // Step 6: Verify (unpad)
  const unpadded = unpad(padded, scheme);
  steps.push({
    stepNumber: stepNumber++,
    type: 'verify',
    title: 'Verify: Remove Padding',
    description: `After decryption, the padding is removed to recover the original data. The ${schemeName(scheme)} scheme ${scheme === 'zero' ? 'removes trailing zeros (ambiguous)' : 'reads the last byte to determine padding length (unambiguous)'}.`,
    scheme,
    values: {
      paddedHex: bytesToHex(padded),
      unpaddedHex: bytesToHex(unpadded),
      recoveredText: bytesToDisplay(unpadded),
      originalText: input,
      match: bytesToDisplay(unpadded) === input ? 'YES' : 'NO',
    },
  });

  return steps;
}

/**
 * Compare all three padding schemes side by side
 */
export function compareSchemes(
  input: string,
  blockSize: number
): Record<PaddingScheme, { padded: number[]; hex: string; blocks: string[] }> {
  const inputBytes = stringToBytes(input);
  const schemes: PaddingScheme[] = ['pkcs7', 'zero', 'ansi-x923'];

  const result = {} as Record<PaddingScheme, { padded: number[]; hex: string; blocks: string[] }>;

  for (const scheme of schemes) {
    const padded = pad(inputBytes, blockSize, scheme);
    const blocks = splitIntoBlocks(padded, blockSize);
    result[scheme] = {
      padded,
      hex: bytesToHex(padded),
      blocks: blocks.map((b) => bytesToHex(b)),
    };
  }

  return result;
}

/**
 * Password Hashing Implementation
 * Educational visualization of iterated hashing with salt
 *
 * IMPORTANT: This is a simplified bcrypt-like function for visualization.
 * Real-world password hashing should use bcrypt, scrypt, or Argon2id
 * via established libraries, never a custom implementation.
 */

import { simpleHash } from './hash';
import type { PasswordHashStep } from '@/lib/types/password-hashing';

export type { PasswordHashStep };

/**
 * Generate a deterministic "random" salt for visualization reproducibility
 * In production, use crypto.getRandomValues()
 */
export function generateSalt(seed?: string): string {
  if (seed) {
    return simpleHash(seed + 'salt-seed').slice(0, 16);
  }
  // Pseudo-random for demo purposes
  const chars = 'abcdef0123456789';
  let salt = '';
  const now = Date.now();
  for (let i = 0; i < 16; i++) {
    salt += chars[(now * (i + 7) * 31) % chars.length];
  }
  return salt;
}

/**
 * Simple iterated hash (bcrypt-like concept)
 * Repeatedly hashes the input to increase computation time
 */
export function iteratedHash(
  password: string,
  salt: string,
  iterations: number
): { hash: string; intermediates: string[] } {
  const intermediates: string[] = [];
  let current = password + salt;

  for (let i = 0; i < iterations; i++) {
    current = simpleHash(current + salt + i.toString());
    if (i < 10 || i === iterations - 1 || i % Math.max(1, Math.floor(iterations / 5)) === 0) {
      intermediates.push(current);
    }
  }

  return { hash: current, intermediates };
}

/**
 * Fast hash (simulating MD5/SHA-256 speed for comparison)
 * Just a single pass, no iteration
 */
export function fastHash(password: string, salt: string): string {
  return simpleHash(password + salt);
}

/**
 * Demonstrate salt purpose: same password with different salts
 */
export function demonstrateSaltPurpose(password: string): {
  noSalt: string;
  salt1: string;
  hash1: string;
  salt2: string;
  hash2: string;
  salt3: string;
  hash3: string;
} {
  const salt1 = generateSalt('user-alice');
  const salt2 = generateSalt('user-bob');
  const salt3 = generateSalt('user-charlie');

  return {
    noSalt: simpleHash(password),
    salt1,
    hash1: iteratedHash(password, salt1, 10).hash,
    salt2,
    hash2: iteratedHash(password, salt2, 10).hash,
    salt3,
    hash3: iteratedHash(password, salt3, 10).hash,
  };
}

/**
 * Demonstrate work factor effect
 * Shows how increasing iterations increases computation time
 */
export function demonstrateWorkFactor(
  password: string,
  salt: string,
  costFactors: number[]
): Array<{ cost: number; iterations: number; hash: string; timeMs: number }> {
  return costFactors.map((cost) => {
    const iterations = Math.pow(2, cost);
    const start = performance.now();
    const { hash } = iteratedHash(password, salt, iterations);
    const timeMs = performance.now() - start;

    return { cost, iterations, hash, timeMs };
  });
}

/**
 * Verify a password against a stored hash
 */
export function verifyPassword(
  password: string,
  salt: string,
  storedHash: string,
  iterations: number
): boolean {
  const { hash } = iteratedHash(password, salt, iterations);
  return hash === storedHash;
}

/**
 * Password hash with detailed steps for visualization
 */
export function passwordHashWithSteps(
  password: string,
  costFactor: number
): PasswordHashStep[] {
  const steps: PasswordHashStep[] = [];
  let stepNumber = 0;
  const iterations = Math.pow(2, costFactor);

  // Step 1: Input
  steps.push({
    stepNumber: stepNumber++,
    type: 'input',
    title: 'Password Input',
    description: `The password "${password}" needs to be hashed for secure storage. Unlike regular hashing, password hashing must be intentionally slow to resist brute-force attacks.`,
    values: {
      password,
      passwordLength: password.length,
      costFactor,
      iterations,
    },
  });

  // Step 2: Generate salt
  const salt = generateSalt(password + costFactor.toString());
  steps.push({
    stepNumber: stepNumber++,
    type: 'generate-salt',
    title: 'Generate Random Salt',
    description: `A unique salt is generated for this password. The salt ensures that even identical passwords produce different hashes, defeating rainbow table attacks.`,
    values: {
      salt,
      saltLength: `${salt.length} characters`,
      purpose: 'Prevents rainbow table attacks and ensures unique hashes',
    },
  });

  // Step 3: Combine
  const combined = password + salt;
  steps.push({
    stepNumber: stepNumber++,
    type: 'combine',
    title: 'Combine Password + Salt',
    description: 'The password and salt are combined before hashing. The salt is stored alongside the hash (it is not secret).',
    values: {
      password,
      salt,
      combined: combined.slice(0, 40) + (combined.length > 40 ? '...' : ''),
    },
  });

  // Step 4: Fast hash comparison
  const fastResult = fastHash(password, salt);
  steps.push({
    stepNumber: stepNumber++,
    type: 'iterate',
    title: 'Why Not a Fast Hash?',
    description: `A single SHA-256 hash takes ~0.000001 seconds. An attacker with a GPU can try billions per second. With cost factor ${costFactor}, we iterate ${iterations.toLocaleString()} times to make each attempt ~${iterations.toLocaleString()}x slower.`,
    values: {
      fastHash: fastResult,
      fastSpeed: '~1 nanosecond per hash',
      attackerSpeed: '~10 billion hashes/sec on GPU',
      slowedBy: `${iterations.toLocaleString()}x with ${iterations.toLocaleString()} iterations`,
    },
    iteration: 1,
    totalIterations: iterations,
  });

  // Step 5: Show iteration process (sample iterations)
  const sampleIterations = Math.min(iterations, 8);
  let current = password + salt;
  for (let i = 0; i < sampleIterations; i++) {
    current = simpleHash(current + salt + i.toString());
    steps.push({
      stepNumber: stepNumber++,
      type: 'stretch',
      title: `Iteration ${i + 1}${i === sampleIterations - 1 && iterations > sampleIterations ? ` (of ${iterations.toLocaleString()})` : ''}`,
      description:
        i === 0
          ? 'First iteration: hash the combined password+salt. Each subsequent iteration feeds the previous hash back in.'
          : i === sampleIterations - 1 && iterations > sampleIterations
            ? `Showing iteration ${i + 1}. The remaining ${(iterations - sampleIterations).toLocaleString()} iterations continue the same process...`
            : `Iteration ${i + 1}: the previous hash is combined with the salt and re-hashed. This key stretching makes brute-force exponentially harder.`,
      values: {
        intermediateHash: current,
        iteration: i + 1,
        progress: `${Math.round(((i + 1) / iterations) * 100)}%`,
      },
      iteration: i + 1,
      totalIterations: iterations,
    });
  }

  // Step 6: Final output
  const { hash: finalHash } = iteratedHash(password, salt, iterations);
  steps.push({
    stepNumber: stepNumber++,
    type: 'output',
    title: 'Final Password Hash',
    description: `After ${iterations.toLocaleString()} iterations, the final hash is produced. This hash, along with the salt and cost factor, is stored in the database. The password itself is never stored.`,
    values: {
      hash: finalHash,
      salt,
      costFactor,
      iterations,
      stored: `$${costFactor}$${salt}$${finalHash}`,
    },
  });

  // Step 7: Verification
  const isValid = verifyPassword(password, salt, finalHash, iterations);
  steps.push({
    stepNumber: stepNumber++,
    type: 'verify',
    title: 'Password Verification',
    description: 'To verify a login, the system re-hashes the entered password with the stored salt and cost factor. If the result matches the stored hash, the password is correct.',
    values: {
      enteredPassword: password,
      storedSalt: salt,
      storedHash: finalHash,
      computedHash: finalHash,
      match: isValid ? 'YES - Login successful' : 'NO - Wrong password',
    },
  });

  return steps;
}

/**
 * RSA Cryptography Implementation for Educational Visualization
 *
 * IMPORTANT SECURITY NOTICE:
 * This is an EDUCATIONAL implementation only. DO NOT use in production.
 * - Uses Math.random() which is NOT cryptographically secure
 * - Uses small prime numbers for visualization clarity
 * - Production systems must use crypto.getRandomValues() and 2048+ bit keys
 *
 * Implements RSA key generation, encryption, and decryption with visualization steps.
 */

import type { RSAKeyPair, RSAStep } from '../types/index.js';

export function isPrime(num: number): boolean {
  if (num <= 1) return false;
  if (num <= 3) return true;
  if (num % 2 === 0 || num % 3 === 0) return false;

  for (let i = 5; i * i <= num; i += 6) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
  }

  return true;
}

export function generatePrime(min: number, max: number): number {
  let prime = Math.floor(Math.random() * (max - min + 1)) + min;

  while (!isPrime(prime)) {
    prime = Math.floor(Math.random() * (max - min + 1)) + min;
  }

  return prime;
}

// Euclidean algorithm
export function gcd(a: number, b: number): number {
  while (b !== 0) {
    const temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

// Extended Euclidean Algorithm
export function modInverse(e: number, phi: number): number {
  let [old_r, r] = [phi, e];
  let [old_s, s] = [0, 1];

  while (r !== 0) {
    const quotient = Math.floor(old_r / r);
    [old_r, r] = [r, old_r - quotient * r];
    [old_s, s] = [s, old_s - quotient * s];
  }

  if (old_s < 0) {
    old_s += phi;
  }

  return old_s;
}

export function modPow(base: number, exp: number, mod: number): number {
  if (mod === 1) return 0;

  let result = 1;
  base = base % mod;

  while (exp > 0) {
    if (exp % 2 === 1) {
      result = (result * base) % mod;
    }
    exp = Math.floor(exp / 2);
    base = (base * base) % mod;
  }

  return result;
}

/**
 * Generate RSA key pair with visualization steps
 */
export function generateRSAKeyPairWithSteps(bitSize: 'small' | 'medium' | 'large' = 'small'): {
  keyPair: RSAKeyPair;
  steps: RSAStep[];
} {
  const steps: RSAStep[] = [];
  let stepNumber = 0;

  // Define prime ranges based on bit size
  const ranges = {
    small: { min: 10, max: 50 },
    medium: { min: 50, max: 200 },
    large: { min: 200, max: 500 },
  };

  const range = ranges[bitSize];

  // Step 1: Select prime p
  const p = generatePrime(range.min, range.max);
  steps.push({
    stepNumber: stepNumber++,
    type: 'prime-selection',
    title: 'Select First Prime (p)',
    description: `Choose a random prime number p. We selected p = ${p}. Prime numbers are the foundation of RSA security.`,
    values: { p },
    formula: 'p = prime number',
  });

  // Step 2: Select prime q (different from p)
  let q = generatePrime(range.min, range.max);
  while (q === p) {
    q = generatePrime(range.min, range.max);
  }
  steps.push({
    stepNumber: stepNumber++,
    type: 'prime-selection',
    title: 'Select Second Prime (q)',
    description: `Choose another random prime number q, different from p. We selected q = ${q}. Using two different primes ensures strong encryption.`,
    values: { p, q },
    formula: 'q = prime number (q ≠ p)',
  });

  // Step 3: Calculate modulus n
  const n = p * q;
  steps.push({
    stepNumber: stepNumber++,
    type: 'modulus-calculation',
    title: 'Calculate Modulus (n)',
    description: `Multiply the two primes: n = p × q = ${p} × ${q} = ${n}. This becomes the modulus for both public and private keys.`,
    values: { p, q, n },
    formula: 'n = p × q',
    calculation: `${p} × ${q} = ${n}`,
  });

  // Step 4: Calculate Euler's totient φ(n)
  const phi = (p - 1) * (q - 1);
  steps.push({
    stepNumber: stepNumber++,
    type: 'phi-calculation',
    title: "Calculate Euler's Totient φ(n)",
    description: `Calculate φ(n) = (p-1) × (q-1) = ${p-1} × ${q-1} = ${phi}. This represents the count of numbers less than n that are coprime to n.`,
    values: { p, q, n, phi },
    formula: 'φ(n) = (p-1) × (q-1)',
    calculation: `(${p}-1) × (${q}-1) = ${p-1} × ${q-1} = ${phi}`,
  });

  // Step 5: Choose public exponent e
  // Common choice: 65537 (2^16 + 1), but we'll use a smaller value for visualization
  let e = 65537;
  if (phi < 65537) {
    e = 3;
    while (e < phi && gcd(e, phi) !== 1) {
      e += 2;
    }
  }

  steps.push({
    stepNumber: stepNumber++,
    type: 'e-selection',
    title: 'Choose Public Exponent (e)',
    description: `Select e such that 1 < e < φ(n) and gcd(e, φ(n)) = 1. We chose e = ${e}. This ensures e and φ(n) are coprime.`,
    values: { p, q, n, phi, e },
    formula: '1 < e < φ(n), gcd(e, φ(n)) = 1',
    calculation: `gcd(${e}, ${phi}) = ${gcd(e, phi)}`,
  });

  // Step 6: Calculate private exponent d
  const d = modInverse(e, phi);
  steps.push({
    stepNumber: stepNumber++,
    type: 'd-calculation',
    title: 'Calculate Private Exponent (d)',
    description: `Find d such that (d × e) mod φ(n) = 1. We calculated d = ${d}. This is the modular multiplicative inverse of e.`,
    values: { p, q, n, phi, e, d },
    formula: '(d × e) mod φ(n) = 1',
    calculation: `(${d} × ${e}) mod ${phi} = ${(d * e) % phi}`,
  });

  // Final step: Key pair generated
  steps.push({
    stepNumber: stepNumber++,
    type: 'complete',
    title: 'RSA Key Pair Generated!',
    description: `Public Key: (e=${e}, n=${n}) - Share this openly. Private Key: (d=${d}, n=${n}) - Keep this secret!`,
    values: { p, q, n, phi, e, d },
  });

  const keyPair: RSAKeyPair = {
    publicKey: { n, e },
    privateKey: { n, d },
    p,
    q,
    phi,
  };

  return { keyPair, steps };
}

/**
 * Encrypt a message with RSA
 */
export function encryptRSA(message: number, publicKey: { n: number; e: number }): number {
  return modPow(message, publicKey.e, publicKey.n);
}

/**
 * Decrypt a message with RSA
 */
export function decryptRSA(ciphertext: number, privateKey: { n: number; d: number }): number {
  return modPow(ciphertext, privateKey.d, privateKey.n);
}

/**
 * Encrypt with visualization steps
 */
export function encryptRSAWithSteps(
  message: number,
  publicKey: { n: number; e: number }
): RSAStep[] {
  const steps: RSAStep[] = [];
  let stepNumber = 0;

  steps.push({
    stepNumber: stepNumber++,
    type: 'encryption',
    title: 'Encryption: Apply Public Key',
    description: `Encrypt the message using the formula: ciphertext = (message^e) mod n`,
    values: { message, e: publicKey.e, n: publicKey.n },
    formula: 'C = M^e mod n',
  });

  const encrypted = encryptRSA(message, publicKey);

  steps.push({
    stepNumber: stepNumber++,
    type: 'encryption',
    title: 'Encryption Complete',
    description: `Ciphertext = (${message}^${publicKey.e}) mod ${publicKey.n} = ${encrypted}`,
    values: { message, encrypted, e: publicKey.e, n: publicKey.n },
    calculation: `${message}^${publicKey.e} mod ${publicKey.n} = ${encrypted}`,
  });

  return steps;
}

/**
 * Decrypt with visualization steps
 */
export function decryptRSAWithSteps(
  ciphertext: number,
  privateKey: { n: number; d: number }
): RSAStep[] {
  const steps: RSAStep[] = [];
  let stepNumber = 0;

  steps.push({
    stepNumber: stepNumber++,
    type: 'decryption',
    title: 'Decryption: Apply Private Key',
    description: `Decrypt the ciphertext using the formula: message = (ciphertext^d) mod n`,
    values: { encrypted: ciphertext, d: privateKey.d, n: privateKey.n },
    formula: 'M = C^d mod n',
  });

  const decrypted = decryptRSA(ciphertext, privateKey);

  steps.push({
    stepNumber: stepNumber++,
    type: 'decryption',
    title: 'Decryption Complete',
    description: `Original message = (${ciphertext}^${privateKey.d}) mod ${privateKey.n} = ${decrypted}`,
    values: { encrypted: ciphertext, decrypted, d: privateKey.d, n: privateKey.n },
    calculation: `${ciphertext}^${privateKey.d} mod ${privateKey.n} = ${decrypted}`,
  });

  return steps;
}

/**
 * Digital Signatures Implementation for Educational Visualization
 *
 * IMPORTANT SECURITY NOTICE:
 * This is an EDUCATIONAL implementation only. DO NOT use in production.
 * - Uses simplified hash function (FNV-1a) for visualization
 * - Uses small key sizes for demonstration clarity
 * - Production systems must use cryptographic libraries with SHA-256+ and 2048+ bit keys
 *
 * Implements digital signature creation and verification with visualization steps.
 */

import type { SignatureStep, RSAKeyPair } from '../types/index.js';
import { modPow } from './rsa.js';
import { simpleHash } from './hash.js';

/**
 * Convert a hex hash string to a number for signing
 * Uses only part of the hash to keep numbers manageable for visualization
 */
function hashToNumber(hash: string, maxValue: number): number {
  // Take first 4 hex characters and convert to number
  const truncatedHash = hash.slice(0, 4);
  const num = parseInt(truncatedHash, 16);
  // Ensure the number is less than n (modulus)
  return num % maxValue;
}

/**
 * Sign a message with visualization steps
 *
 * Digital signatures work by:
 * 1. Hashing the message to create a fixed-size digest
 * 2. Encrypting the hash with the PRIVATE key (this is the signature)
 *
 * Anyone can verify by:
 * 1. Decrypting the signature with the PUBLIC key to get the hash
 * 2. Hashing the original message
 * 3. Comparing the two hashes
 */
export function signMessageWithSteps(
  message: string,
  keyPair: RSAKeyPair
): { signature: number; steps: SignatureStep[] } {
  const steps: SignatureStep[] = [];
  let stepNumber = 0;

  // Step 1: Message input
  steps.push({
    stepNumber: stepNumber++,
    type: 'message-input',
    title: 'Input Message',
    description: `The message to sign: "${message.length > 50 ? message.slice(0, 50) + '...' : message}"`,
    values: {
      message,
    },
  });

  // Step 2: Hash the message
  const messageHash = simpleHash(message);
  steps.push({
    stepNumber: stepNumber++,
    type: 'hash-generation',
    title: 'Generate Message Hash',
    description: `Hash the message using a cryptographic hash function. This creates a fixed-size "fingerprint" of the message. Hash = ${messageHash}`,
    values: {
      message,
      messageHash,
    },
    formula: 'H = hash(message)',
  });

  // Step 3: Convert hash to number and sign with private key
  const hashNum = hashToNumber(messageHash, keyPair.publicKey.n);
  const signature = modPow(hashNum, keyPair.privateKey.d, keyPair.privateKey.n);

  steps.push({
    stepNumber: stepNumber++,
    type: 'sign-hash',
    title: 'Sign the Hash',
    description: `Encrypt the hash using your PRIVATE key. This is the opposite of normal RSA encryption! Only the private key holder can create this signature.`,
    values: {
      messageHash,
      signature,
      d: keyPair.privateKey.d,
      n: keyPair.privateKey.n,
    },
    formula: 'S = H^d mod n',
    calculation: `${hashNum}^${keyPair.privateKey.d} mod ${keyPair.privateKey.n} = ${signature}`,
  });

  // Step 4: Signature complete
  steps.push({
    stepNumber: stepNumber++,
    type: 'signature-complete',
    title: 'Signature Created!',
    description: `Your digital signature is: ${signature}. Send this along with your message. Anyone with your public key can verify it came from you.`,
    values: {
      message,
      messageHash,
      signature,
    },
  });

  return { signature, steps };
}

/**
 * Verify a signature with visualization steps
 */
export function verifySignatureWithSteps(
  message: string,
  signature: number,
  publicKey: { n: number; e: number }
): { isValid: boolean; steps: SignatureStep[] } {
  const steps: SignatureStep[] = [];
  let stepNumber = 0;

  // Step 1: Verify inputs
  steps.push({
    stepNumber: stepNumber++,
    type: 'verify-input',
    title: 'Verification Inputs',
    description: `Received message: "${message.length > 50 ? message.slice(0, 50) + '...' : message}" with signature: ${signature}. Let's verify it came from the claimed sender.`,
    values: {
      message,
      signature,
      e: publicKey.e,
      n: publicKey.n,
    },
  });

  // Step 2: Hash the received message
  const messageHash = simpleHash(message);
  const expectedHashNum = hashToNumber(messageHash, publicKey.n);

  steps.push({
    stepNumber: stepNumber++,
    type: 'verify-hash',
    title: 'Hash the Message',
    description: `Hash the received message using the same hash function. This gives us the expected hash value: ${messageHash}`,
    values: {
      message,
      messageHash,
    },
    formula: 'H_expected = hash(message)',
  });

  // Step 3: Decrypt the signature with public key
  const decryptedHashNum = modPow(signature, publicKey.e, publicKey.n);

  steps.push({
    stepNumber: stepNumber++,
    type: 'decrypt-signature',
    title: 'Decrypt Signature',
    description: `Use the sender's PUBLIC key to decrypt the signature. This reveals the hash that was originally signed.`,
    values: {
      signature,
      decryptedHash: decryptedHashNum.toString(16),
      e: publicKey.e,
      n: publicKey.n,
    },
    formula: 'H_decrypted = S^e mod n',
    calculation: `${signature}^${publicKey.e} mod ${publicKey.n} = ${decryptedHashNum}`,
  });

  // Step 4: Compare hashes
  const isValid = decryptedHashNum === expectedHashNum;

  steps.push({
    stepNumber: stepNumber++,
    type: 'compare-hashes',
    title: 'Compare Hashes',
    description: `Compare the decrypted hash (${decryptedHashNum}) with the calculated hash (${expectedHashNum}).`,
    values: {
      messageHash,
      decryptedHash: decryptedHashNum.toString(16),
      isValid,
    },
    formula: 'H_decrypted == H_expected ?',
    calculation: `${decryptedHashNum} ${isValid ? '==' : '!='} ${expectedHashNum}`,
  });

  // Step 5: Final result
  steps.push({
    stepNumber: stepNumber++,
    type: 'verify-result',
    title: isValid ? 'Signature Valid!' : 'Signature Invalid!',
    description: isValid
      ? 'The hashes match! This proves: (1) The message was signed by the private key holder, (2) The message has not been tampered with.'
      : 'The hashes do NOT match! Either the message was altered, or it was not signed by the claimed sender.',
    values: {
      isValid,
    },
  });

  return { isValid, steps };
}

/**
 * Simple sign function without steps (for quick operations)
 */
export function signMessage(message: string, privateKey: { n: number; d: number }): number {
  const messageHash = simpleHash(message);
  const hashNum = hashToNumber(messageHash, privateKey.n);
  return modPow(hashNum, privateKey.d, privateKey.n);
}

/**
 * Simple verify function without steps (for quick operations)
 */
export function verifySignature(
  message: string,
  signature: number,
  publicKey: { n: number; e: number }
): boolean {
  const messageHash = simpleHash(message);
  const expectedHashNum = hashToNumber(messageHash, publicKey.n);
  const decryptedHashNum = modPow(signature, publicKey.e, publicKey.n);
  return decryptedHashNum === expectedHashNum;
}

