    steps,
    currentStep,
    isPlaying,
    speed,
    setSteps,
    play,
    pause,
    reset,
    nextStep,
    previousStep,
    setSpeed,
  } = useVisualizationStore();

  const [password, setPassword] = useState('correcthorsebatterystaple');
  const [costFactor, setCostFactor] = useState(4);
